# Setup script to prepare the environment
mkdir -p /home/user/workspace/src
cd /home/user/workspace

# Install websockets
pip install websockets

# Create C files
cat << 'EOF' > src/modA.c
int getA() {
    return 10;
}
EOF

cat << 'EOF' > src/modB.c
extern int getA();
int getB() {
    return getA() + 20;
}
EOF

cat << 'EOF' > src/modC.c
extern int getA();
int getC() {
    return getA() + 30;
}
EOF

cat << 'EOF' > src/modD.c
extern int getB();
extern int getC();
int getD() {
    return getB() + getC();
}
EOF

# Create WebSocket server
cat << 'EOF' > ws_server.py
import asyncio
import websockets
import json

async def handler(websocket, path):
    graph = {
        "modA": [],
        "modB": ["modA"],
        "modC": ["modA"],
        "modD": ["modB", "modC"]
    }
    await websocket.send(json.dumps(graph))
    await asyncio.Future()  # run forever

start_server = websockets.serve(handler, "localhost", 8765)
asyncio.get_event_loop().run_until_complete(start_server)
asyncio.get_event_loop().run_forever()
EOF

# Correct answer verification:
# modA = 10
# modB = 10 + 20 = 30
# modC = 10 + 30 = 40
# modD = 30 + 40 = 70
# result.txt must contain the string "70" exactly (whitespace around it is fine).
